from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def get_document_client(config):
    return DocumentIntelligenceClient(config['endpoint'], AzureKeyCredential(config['api_key']))

class DocumentRequest:
    def __init__(self, document_bytes, mime_type):
        self.document_bytes = document_bytes
        self.mime_type = mime_type

class DocumentResponse:
    def __init__(self, content):
        self.content = content

import re

def check_unsafe_content(text):
    unsafe_patterns = [r'\b(porn|sex|nudity)\b', r'\b(hate|violence)\b']
    for pattern in unsafe_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return True
    return False

import spacy

def extract_structured_fields(text):
    nlp = spacy.load('en_core_web_sm')
    doc = nlp(text)
    fields = {}
    for ent in doc.ents:
        fields[ent.label_] = ent.text
    return fields
